42	/** Ash's tap on "Send to MonoCode Hub lead". A Lead with no chat yet is opened first, and the words follow once it has one. */
43	export async function sendToHubLead(prompt: string, opts: { waitMs?: number } = {}): Promise<SendResult> {
44	  const lead = hubLeadMono();
45	  if (!lead) return { ok: false, reason: "The MonoCode Hub lead isn't on your Monos list yet." };
46	  const name = agentName(lead);
47	  const hands = pageActionsHost();
48	  if (!hands) return { ok: false, reason: "The app isn't ready to send that yet. Open the MonoCode Hub lead and ask there." };
49	  let chat = lead.sessionId;
50	  if (!chat) {
51	    hands.openMono(lead.id);
52	    const end = Date.now() + (opts.waitMs ?? 4000);
53	    while (!chat && Date.now() < end) {
54	      await new Promise((r) => setTimeout(r, 50));
55	      chat = findMono(lead.id)?.sessionId;
56	    }
57	    if (!chat) return { ok: false, reason: `${name} is opening. Ask there in your own words.` };
58	  }
59	  const sent = await hands.send(chat, appChangeBrief(prompt)).catch(() => false);
60	  return sent ? { ok: true, lead: name } : { ok: false, reason: `${name} couldn't take a message right now. Open it and ask there.` };
61	}
