11	/**
12	 * The seam for Level 2 changes (docs/hub-change-contract.md): Change the hub, Edit Today by chat, and Connect data.
13	 * A seated Mono asks Claude Code for a preview build; Ash sees Now beside Preview, then Apply or Discard; Apply adds a
14	 * Bot changes row whose Undo reverts it. Every call goes through the hub transport; unwired ones say Not connected yet.
15	 */
16	export type ChangeFlow = "hub" | "today" | "connect";
17	export type ChangeRequest = { flow: ChangeFlow; projectId: string; monoId: string; prompt: string };
18	/** One side of the comparison: what the backend's preview build shows, as sections of rows (and optionally an image). */
19	export type ChangeSide = { image?: string; sections: { title: string; rows: string[] }[] };
20	export type ChangePreview = { previewId: string; title: string; by: string; now: ChangeSide; preview: ChangeSide };
21	export type ChangeResult =
22	  | { status: "ready"; preview: ChangePreview }
23	  | { status: "turned-down"; reason: string }
24	  | { status: "not-connected"; reason: string }
25	  /** The Mono is still building the preview: Try again collects it (the same request never builds twice). */
26	  | { status: "building"; reason: string }
27	  /** It changes the app itself (a screen's look or behaviour): the MonoCode Hub lead's work (appChange.ts). */
28	  | { status: "app-change"; reason: string }
29	  | { status: "error"; reason: string };
