31	export const CHANGE_ACTIONS = { preview: "ash-hub-change-preview", apply: "ash-hub-change-apply", discard: "ash-hub-change-discard", undo: "ash-hub-change-undo", redo: "ash-hub-change-redo" } as const;
32	export const SEATED_ONLY = "You ask, and one of your own Monos builds it. Temporary workers can't.";
33	export const HUB_CANT = "This can't change keys or the Keychain, account sign-ins, delete projects or Monos, or skip the preview.";
34	export const FLOW_LABEL: Record<ChangeFlow, string> = { hub: "Change the hub", today: "Edit Today", connect: "Connect data" };
35	const NOT_WIRED: Record<ChangeFlow, string> = {
36	  hub: "Changing the hub with a preview build isn't wired to the backend yet.",
37	  today: "Editing Today by chat isn't wired to the backend yet.",
38	  connect: "Connecting your own data isn't wired to the backend yet.",
39	};
40	const DEV_STUB_KEY = "monocode:hub-change-dev-stub";
41	export function changeStubOn(): boolean {
42	  try {
43	    return localStorage.getItem(DEV_STUB_KEY) === "1";
44	  } catch {
45	    return false;
46	  }
