49	export type ChangeDeps = { transport?: HubTransport; roster?: readonly { id: string }[]; stub?: boolean };
50	const NAMES: Record<string, string> = { "projects-manager": "Projects Manager", "chief-of-staff": "Chief of Staff" };
51	/** Dev stub only: words that ask for a screen's look or behaviour. */
52	const STUB_SCREEN = /\b(bigger|smaller|colou?r|font|rounder|button|screen|dark mode|look)\b/i;
53	
54	function validPreview(raw: unknown): ChangePreview | undefined {
55	  const x = raw as ChangePreview | undefined;
56	  const side = (s: ChangeSide | undefined) => !!s && Array.isArray(s.sections) && s.sections.every((sec) => typeof sec.title === "string" && Array.isArray(sec.rows));
57	  return x && typeof x.previewId === "string" && typeof x.title === "string" && side(x.now) && side(x.preview) ? x : undefined;
58	}
59	
60	/** What an applied, undone or redone change can move: the sidebar, Today, and the history itself. */
61	const MOVES: readonly HubSlice[] = ["changes", "layout", "projects"];
62	
63	/** Through the live store when there is one (the slices it moves are read again at once), else the given transport. */
64	async function call<T>(action: string, payload: Record<string, unknown>, deps: ChangeDeps, reload: readonly HubSlice[] = []): Promise<T> {
65	  const store = deps.transport ? undefined : liveHubStore();
66	  if (store) return store.act<T>(action, payload, reload);
67	  return (deps.transport ?? tauriHubTransport).call<T>(action, payload);
68	}
69	function notConnected(flow: ChangeFlow, e: unknown): ChangeResult {
70	  const err = e instanceof HubCallError ? e : toHubError(e);
71	  if (err.isDown || err.kind === "refused") return { status: "not-connected", reason: NOT_WIRED[flow] };
72	  if (err.kind === "timeout") return { status: "building", reason: "The preview is taking a while. Press Try again in a moment to see it." };
73	  if (isStillBuilding(err.message)) return { status: "building", reason: err.message };
74	  if (isAppChange(err.message)) return { status: "app-change", reason: err.message };
75	  // Ash OS says "isn't wired" for Connect data before any Mono runs.
76	  if (/isn't wired/i.test(err.message)) return { status: "not-connected", reason: err.message };
77	  if (/turned it down|doesn't fit/i.test(err.message) || err.message === SEATED_ONLY) return { status: "turned-down", reason: err.message };
78	  return { status: "error", reason: plainProviderError(err.message) || "That didn't go through." };
79	}
