90	fn git(dir: &Path, args: &[&str]) -> Result<String, String> {
91	    let mut command = Command::new("git");
92	    crate::hide_window_console(&mut command);
93	    let output = command
94	        .arg("-C")
95	        .arg(dir)
96	        .args([
97	            "-c",
98	            "user.name=MonoCode Hub",
99	            "-c",
100	            "user.email=hub@monocode.invalid",
101	            "-c",
102	            "commit.gpgsign=false",
103	        ])
104	        .args(args)
105	        .env("GIT_TERMINAL_PROMPT", "0")
106	        .env("PATH", crate::harness::cached_gui_search_path())
107	        .output()
108	        .map_err(|e| e.to_string())?;
109	    if !output.status.success() {
110	        let err = String::from_utf8_lossy(&output.stderr).trim().to_string();
111	        let out = String::from_utf8_lossy(&output.stdout).trim().to_string();
112	        return Err(if err.is_empty() { out } else { err });
113	    }
114	    Ok(String::from_utf8_lossy(&output.stdout).into_owned())
115	}
