511	/** What a Need asks of Ash, for grouping a long list (Board 22 Oct: "102 things waiting" read as one unsorted list). */
512	export type NeedKind = "decide" | "check" | "read";
513	const NEED_KIND_LABEL: Record<NeedKind, string> = { decide: "To decide", check: "To check", read: "To look at" };
514	export function needKind(need: Need): NeedKind {
515	  if (need.jobId || need.actionTarget?.startsWith("question:")) return "decide";
516	  if (need.actionType === "accept" || need.canMarkSeen) return "check";
517	  return "read";
518	}
519	
520	/** A project's shown Needs, like with like: what to decide, what to check, what to look at; a heading only when mixed. */
521	function NeedGroups({ needs, onSheet }: { needs: readonly Need[]; onSheet: (sheet: SheetFor) => void }) {
522	  const groups = (["decide", "check", "read"] as const)
523	    .map((kind) => ({ kind, rows: needs.filter((n) => needKind(n) === kind) }))
524	    .filter((g) => g.rows.length);
525	  if (groups.length < 2) return <>{needs.map((n) => <NeedRow key={n.id} need={n} onSheet={onSheet} counted />)}</>;
526	  return (
527	    <>
528	      {groups.map((g) => (
529	        <div key={g.kind} className="flex flex-col" data-hub-need-group={g.kind}>
530	          <h3 className="mt-2 px-2 pb-0.5 text-[11px] font-normal text-content/50">
531	            {NEED_KIND_LABEL[g.kind]} · {g.rows.length}
532	          </h3>
533	          {g.rows.map((n) => (
534	            <NeedRow key={n.id} need={n} onSheet={onSheet} counted />
535	          ))}
536	        </div>
537	      ))}
538	    </>
539	  );
540	}
