16	function httpTransport(baseUrl: () => string, token: () => string): HubTransport {
17	  return {
18	    call: (action, payload = {}) =>
19	      new Promise((resolve, reject) => {
20	        const body = JSON.stringify(payload);
21	        const req = http.request(
22	          `${baseUrl()}/api/${action}`,
23	          { method: "POST", headers: { Authorization: `Bearer ${token()}`, "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) } },
24	          (res) => {
25	            let raw = "";
26	            res.on("data", (c) => (raw += c));
27	            res.on("end", () => {
28	              const json = JSON.parse(raw);
29	              if (json.ok) resolve(json.result);
30	              else reject(new HubCallError("error", json.error));
31	            });
32	          },
33	        );
34	        req.on("error", () => reject(new HubCallError("unreachable", "Ash OS isn't running.")));
35	        req.end(body);
36	      }),
37	    openFeed: (_after, handlers) => {
38	      handlers.onState({ connected: false, message: "polling in this test" });
39	      return () => undefined;
40	    },
41	  };
42	}
