.agent-markdown [data-streamdown="code-block"] {
  /* Streamdown sets inline content-visibility:auto with a 200px estimate.
     WebKit can use that estimate during a streaming commit, then shrink the
     scroll range on the next frame. Loaded transcript turns already use real
     heights; their code fences must do the same, including nested fences. */
  content-visibility: visible !important;
  contain-intrinsic-size: none !important;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
}

.agent-markdown [data-streamdown="table-wrapper"] {
