}

.agent-markdown .markdown-code-shell [data-streamdown="code-block"] {
  margin-block: 0;
}

.agent-markdown .markdown-code-copy {
  appearance: none;
  position: absolute;
  z-index: 2;
  top: 6px;
  right: 8px;
  display: grid;
  width: 24px;
  height: 24px;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 6px;
  outline: none;
  background: transparent;
  box-shadow: none;
  color: color-mix(in srgb, var(--color-content) 45%, transparent);
  transition:
    color 160ms ease,
    background-color 160ms ease;
}

.agent-markdown .markdown-code-copy:hover {
  background: color-mix(in srgb, var(--color-content) 10%, transparent);
  color: var(--color-content);
}

.agent-markdown .markdown-code-copy:focus-visible {
  background: color-mix(in srgb, var(--color-content) 10%, transparent);
  color: var(--color-content);
}
