  --inset-surface: var(--wt-dark-surface, #0d0d0d);
  --inset-panel: var(--wt-dark-panel, #060606);
  --inset-glass-alpha: 0.8;
  --inset-panel-alpha: 0.4;
  --inset-wash: hsl(0 0% 92% / 0.05);
