4461	/**
4462	 * Sessions started through the app CLI are named `app-<caller>-<request>`, so
4463	 * each finds its caller among the listed sessions. One a started session
4464	 * started in turn joins the same top-level session. Sessions whose caller is
4465	 * not listed, such as a Mono's, stay where they are.
4466	 */
4467	export function groupStartedSessions<T extends { id: string }>(
4468	  sessions: readonly T[],
4469	): { byParent: ReadonlyMap<string, T[]>; childIds: ReadonlySet<string> } {
4470	  const ids = new Set(sessions.map((session) => session.id));
4471	  const callerOf = (id: string) => startedSessionCaller(id, ids);
4472	  const byParent = new Map<string, T[]>();
4473	  const childIds = new Set<string>();
4474	  for (const session of sessions) {
4475	    let root = callerOf(session.id);
4476	    if (!root) continue;
4477	    const seen = new Set([session.id]);
4478	    for (let up = callerOf(root); up && !seen.has(up); up = callerOf(up)) {
4479	      seen.add(root);
4480	      root = up;
4481	    }
4482	    childIds.add(session.id);
4483	    const list = byParent.get(root);
4484	    if (list) list.push(session);
4485	    else byParent.set(root, [session]);
4486	  }
4487	  return { byParent, childIds };
4488	}
