65	const MAX_NOTE_PICKER = 8;
66	const NOTE_SLUG_RE = /(^|\s)@note\/([A-Za-z0-9_-]+)/g;
67	
68	let cache: Note[] | null = null;
69	let inflight: Promise<Note[]> | null = null;
70	
71	export function peekNotes(): Note[] | null {
72	  return cache;
73	}
74	
75	export function invalidateNotes() {
76	  cache = null;
77	}
78	
79	export async function loadNotes(refresh = false): Promise<Note[]> {
80	  if (!refresh && cache) return cache;
81	  if (!refresh && inflight) return inflight;
82	
83	  const promise = invoke<Note[]>("notes_list")
84	    .then((notes) => {
85	      cache = notes;
86	      return notes;
87	    })
88	    .catch(() => {
89	      if (!cache) cache = [];
90	      return cache;
91	    })
92	    .finally(() => {
93	      if (inflight === promise) inflight = null;
94	    });
95	  inflight = promise;
96	  return promise;
97	}
