99	export async function getNote(id: string): Promise<Note | null> {
100	  const note = await invoke<Note | null>("notes_get", { id });
101	  return note;
102	}
103	
104	export async function upsertNote(note: NoteUpsert): Promise<Note> {
105	  const saved = await invoke<Note>("notes_upsert", { note });
106	  cache = null;
107	  return saved;
108	}
