115	export async function createNote(input: {
116	  title?: string;
117	  body?: string;
118	  tags?: string[];
119	  sourceSessionId?: string;
120	  sourceCwd?: string;
121	}): Promise<Note> {
122	  const body = (input.body ?? "").replace(/\r\n?/g, "\n");
123	  return upsertNote({
124	    id: crypto.randomUUID(),
125	    title: (input.title ?? noteTitle(body)).slice(0, MAX_TITLE),
126	    body,
127	    tags: normalizeNoteTags(input.tags ?? []),
128	    ...(input.sourceSessionId
129	      ? { sourceSessionId: input.sourceSessionId }
130	      : {}),
131	    ...(input.sourceCwd ? { sourceCwd: input.sourceCwd } : {}),
132	  });
133	}
