135	/** Canonical, case-insensitive tags for storage and filtering. */
136	export function normalizeNoteTags(tags: readonly string[]): string[] {
137	  const normalized: string[] = [];
138	  const seen = new Set<string>();
139	  for (const input of tags) {
140	    const tag = input
141	      .trim()
142	      .replace(/^#+/, "")
143	      .replace(/\s+/g, "-")
144	      .toLowerCase()
145	      .slice(0, MAX_NOTE_TAG_LENGTH)
146	      .replace(/-+$/g, "");
147	    if (!tag || seen.has(tag)) continue;
148	    seen.add(tag);
149	    normalized.push(tag);
150	    if (normalized.length === MAX_NOTE_TAGS) break;
151	  }
152	  return normalized;
153	}
