163	export function notesAsProjectFiles(notes: Note[]): ProjectFile[] {
164	  return notes.map((note) => ({
165	    name: note.title,
166	    path: `${NOTE_PATH_PREFIX}${note.id}`,
167	    relative: noteMentionLabel(note),
168	  }));
