const NOTES_CHANNEL = "monocode:notes";
let notesBusCache: BroadcastChannel | null | undefined;

/** One channel for every window. A note saved in one shows up in the others. */
function notesBus(): BroadcastChannel | null {
  if (notesBusCache !== undefined) return notesBusCache;
  if (typeof BroadcastChannel === "undefined") {
    notesBusCache = null;
    return null;
  }
  try {
    const bus = new BroadcastChannel(NOTES_CHANNEL);
    bus.onmessage = () => {
      cache = null;
      if (typeof window !== "undefined") {
        window.dispatchEvent(new Event(NOTES_CHANGED_EVENT));
      }
    };
    notesBusCache = bus;
  } catch {
    notesBusCache = null;
  }
  return notesBusCache;
}

function publishNoteChange() {
  try {
    notesBus()?.postMessage("changed");
  } catch {
    // The other window can already be gone.
  }
}

