}

function pinnedKey(chatId: string): string {
  return `monocode.pinnedConversations:${chatId}`;
}

function readPinnedConversations(chatId: string): string[] {
  try {
    const raw = localStorage.getItem(pinnedKey(chatId));
    const parsed: unknown = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed.filter((id) => typeof id === "string") : [];
  } catch {
    return [];
  }
}

