{"type":"assistant","message":{"id":"278f6196-fd14-9c87-96bb-27c8a18a42b1","type":"message","role":"assistant","model":"grok-4.7-build","stop_sequence":null,"usage":{"input_tokens":97082,"output_tokens":0},"content":[{"type":"tool_use","id":"call-14162545-9a97-48e0-9fd8-5083e4497a49-100","name":"Write","input":{"file_path":"/private/var/folders/b4/8qh0t36j0_g9srqzx1g5t3z40000gn/T/monocode-realtest-eWN39Z/home/Library/Application Support/com.ash.monocode-hub.dev.cos-r62-realtest/hub-changes/hc-mvvxt01p3445/src/features/sessions/ui/ChatFind.tsx","content":"import { useEffect, useMemo, useRef, useState } from "react";
import { X } from "../../../shared/ui/icons";
import type { Block } from "../model/session";
import { requestTranscriptJump } from "../model/transcriptJump";

function haystack(block: Block): string {
  return [block.text, block.tool?.title, block.tool?.detail, block.tool?.command]
    .filter((part) => !!part)
    .join("\n");
}

/** Visible turns whose text contains the query, in chat order. */
export function chatFindMatches(blocks: readonly Block[], query: string): string[] {
  const needle = query.trim().toLowerCase();
  if (!needle) return [];
  const found: string[] = [];
  for (const block of blocks) {
    if (block.internal || block.monoSessionCompletion || block.monoCheck) continue;
    if (haystack(block).toLowerCase().includes(needle)) found.push(block.id);
  }
  return found;
}

/**
 * Find inside the open chat. Enter jumps to the next match, Shift+Enter to the
 * previous one, Escape closes it.
 */
export function ChatFind({
  sessionId,
  blocks,
  focusToken,
  onClose,
}: {
  sessionId: string;
  blocks: readonly Block[];
  focusToken: number;
  onClose: () => void;
}) {
  const [query, setQuery] = useState("");
  const [index, setIndex] = useState(0);
  const input = useRef<HTMLInputElement>(null);
  const matches = useMemo(() => chatFindMatches(blocks, query), [blocks, query]);
  const at = matches.length === 0 ? 0 : index % matches.length;

  useEffect(() => {
    input.current?.focus();
    input.current?.select();
  }, [focusToken]);

  useEffect(() => {
    const blockId = matches[at];
    const needle = query.trim();
    if (!blockId || !needle) return;
    requestTranscriptJump(sessionId, blockId, needle);
  }, [matches, at, query, sessionId]);

  const go = (delta: number) => {
    if (matches.length === 0) return;
    setIndex((current) => (current + delta + matches.length) % matches.length);
  };

  return (
    <div
      data-chat-find=""
      className="absolute top-2 right-2 z-30 flex items-center gap-1.5 rounded-md border border-stroke bg-background-base px-2 py-1 text-[13px] text-content"
      onKeyDown={(event) => {
        if (event.key === "Escape") {
          event.preventDefault();
          event.stopPropagation();
          onClose();
        } else if (event.key === "Enter") {
          event.preventDefault();
          go(event.shiftKey ? -1 : 1);
        }
      }}
    >
      <input
        ref={input}
        value={query}
        aria-label="Find in chat"
        placeholder="Find"
        onChange={(event) => {
          setQuery(event.target.value);
          setIndex(0);
        }}
        className="w-44 bg-transparent text-content outline-none placeholder:text-content/40"
      />
      <span className="shrink-0 tabular-nums text-[11px] text-content/50">
        {query.trim() ? (matches.length ? `${at + 1}/${matches.length}` : "0") : ""}
      </span>
      <button
        type="button"
        aria-label="Close find"
        onClick={onClose}
        className="grid size-5 place-items-center rounded-md text-content/50 hover:bg-content/8 hover:text-content"
      >
        <X className="size-3" strokeWidth={1.75} />
      </button>
    </div>
  );
}
