/**
 * Find inside the open chat. Enter jumps to the next match, Shift+Enter to the
 * previous one, Escape closes it.
 */
export function ChatFind({
  sessionId,
  blocks,
  focusToken,
  onClose,
}: {
  sessionId: string;
  blocks: readonly Block[];
  focusToken: number;
  onClose: () => void;
}) {
  const [query, setQuery] = useState("");
  const [index, setIndex] = useState(0);
  const input = useRef<HTMLInputElement>(null);
  const matches = useMemo(() => chatFindMatches(blocks, query), [blocks, query]);
  const at = matches.length === 0 ? 0 : index % matches.length;

  useEffect(() => {
    input.current?.focus();
    input.current?.select();
  }, [focusToken]);

  useEffect(() => {
    const blockId = matches[at];
    const needle = query.trim();
    if (!blockId || !needle) return;
    requestTranscriptJump(sessionId, blockId, needle);
  }, [matches, at, query, sessionId]);

  const go = (delta: number) => {
    if (matches.length === 0) return;
    setIndex((current) => (current + delta + matches.length) % matches.length);
  };

  return (
    <div
      data-chat-find=""
      className="absolute top-2 right-2 z-30 flex items-center gap-1.5 rounded-md border border-stroke bg-background-base px-2 py-1 text-[13px] text-content"
      onKeyDown={(event) => {
        if (event.key === "Escape") {
          event.preventDefault();
          event.stopPropagation();
          onClose();
        } else if (event.key === "Enter") {
          event.preventDefault();
          go(event.shiftKey ? -1 : 1);
        }
      }}
    >
      <input
        ref={input}
        value={query}
        aria-label="Find in chat"
        placeholder="Find"
        onChange={(event) => {
          setQuery(event.target.value);
          setIndex(0);
        }}
        className="w-44 bg-transparent text-content outline-none placeholder:text-content/40"
      />
      <span className="shrink-0 tabular-nums text-[11px] text-content/50">
        {query.trim() ? (matches.length ? `${at + 1}/${matches.length}` : "0") : ""}
      </span>
      <button
        type="button"
        aria-label="Close find"
        onClick={onClose}
        className="grid size-5 place-items-center rounded-md text-content/50 hover:bg-content/8 hover:text-content"
      >
        <X className="size-3" strokeWidth={1.75} />
      </button>
    </div>
  );
}
