  counts: ReadonlyMap<string, number>;
  noteReply: (sessionId: string) => void;
  /** Ash answered this chat. Drop the badge, and don't bring it back for the reply to that answer. */
  clearAnswered: (sessionId: string) => void;
} {
  const [, rerender] = useReducer((tick: number) => tick + 1, 0);
  const busyRef = useRef(busySessionIds);
  const focusedRef = useRef(activeSessionId);
  const trackedRef = useRef(trackedIds);
  const countsRef = useRef<ReadonlyMap<string, number>>(new Map());
  /** The next time one of these leaves busy, that finish is the reply to Ash, not a new unseen reply. */
  const suppressRef = useRef(new Set<string>());
  if (
    busyRef.current !== busySessionIds ||
    focusedRef.current !== activeSessionId ||
    trackedRef.current !== trackedIds
  ) {
    const previousCounts = countsRef.current;
    const next = nextUnseenReplyCounts({
      previousBusyIds: busyRef.current,
      busyIds: busySessionIds,
      previousCounts,
      focusedSessionId: activeSessionId,
      trackedIds,
    });
    for (const id of suppressRef.current) {
      const leftBusy = busyRef.current.has(id) && !busySessionIds.has(id);
      if (!leftBusy) continue;
      const prior = previousCounts.get(id);
      if (prior == null) next.delete(id);
      else next.set(id, prior);
      suppressRef.current.delete(id);
    }
    countsRef.current = next;
    busyRef.current = busySessionIds;
    focusedRef.current = activeSessionId;
    trackedRef.current = trackedIds;
  }
  const noteReply = useCallback((sessionId: string) => {
    if (sessionId === focusedRef.current || !trackedRef.current.has(sessionId))
      return;
    const next = new Map(countsRef.current);
    next.set(sessionId, (next.get(sessionId) ?? 0) + 1);
    countsRef.current = next;
    rerender();
  }, []);
  const clearAnswered = useCallback((sessionId: string) => {
    if (!trackedRef.current.has(sessionId)) return;
    suppressRef.current.add(sessionId);
    if (!countsRef.current.has(sessionId)) return;
    const next = new Map(countsRef.current);
    next.delete(sessionId);
    countsRef.current = next;
    rerender();
