/** A short "Archived" note with Undo. A newer archive replaces it. */
export function ArchiveUndoToast({
  title,
  onUndo,
  onDismiss,
}: {
  title: string;
  onUndo: () => void;
  onDismiss: () => void;
}) {
  useEffect(() => {
    const timer = window.setTimeout(onDismiss, 6000);
    return () => window.clearTimeout(timer);
  }, [onDismiss]);
  return (
    <div
      data-archive-undo=""
      role="status"
      className="pointer-events-auto fixed bottom-4 left-1/2 z-50 flex max-w-[min(24rem,calc(100%-2rem))] -translate-x-1/2 items-center gap-3 rounded-md border border-stroke bg-background-base px-3 py-2 text-[13px] text-content"
    >
      <span className="min-w-0 truncate">Archived {title}</span>
      <button
        type="button"
        onClick={onUndo}
        className="shrink-0 text-accent hover:underline"
      >
        Undo
      </button>
    </div>
  );
}
